import React from 'react';
import { CircularProgress } from '@mui/material';
import { SearchX } from 'lucide-react';

export default function AdminRecordState({ loading, empty, searching }) {
  if (!loading && !empty) return null;
  return <div className="admin-record-state" role="status">
    {loading ? <><CircularProgress size={24} /><strong>Loading records</strong><span>Please wait while your records are retrieved.</span></> : <><SearchX size={30} /><strong>{searching ? 'No matching records' : 'No records to display'}</strong><span>{searching ? 'Try a different search or clear the search field.' : 'Records will appear here when they are available.'}</span></>}
  </div>;
}
