import React, { useContext, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Button, Menu, MenuItem } from '@mui/material';
import { Home, UserRound, LogOut, Menu as MenuIcon } from 'lucide-react';
import { ContextData } from '../../../../../context/Context';
import { Getrequest } from '../../../../../context/AxiosRequest';
import { toast } from 'react-toastify';

export default function Header() {
  const Navigate = useNavigate();
  const { accesstoken, setaccesstoken, setUserTokens } = useContext(ContextData);
  const [profileAnchor, setProfileAnchor] = useState(null);
  const [mobileAnchor, setMobileAnchor] = useState(null);

  const HandleLogout = async () => {
    await Getrequest('/auth/logout', accesstoken);
    Navigate('/home');
    setaccesstoken(null);
    setUserTokens('');
    toast.success('Logout');
  };

  const goTo = (path) => {
    setProfileAnchor(null);
    setMobileAnchor(null);
    Navigate(path);
  };

  return <div className="applicant-app-header">
    <Link className="applicant-header-brand" to="/application/home"><img src="/assets/newksslb-tp.png" alt="KADSSLB logo" /><span><strong>KADSSLB</strong><small>Applicant portal</small></span></Link>
    <nav className="applicant-desktop-nav" aria-label="Applicant navigation">
      <Button startIcon={<Home size={18} />} onClick={() => goTo('/application/home')}>Dashboard</Button>
      <Button startIcon={<UserRound size={18} />} aria-controls={profileAnchor ? 'applicant-profile-menu' : undefined} aria-expanded={Boolean(profileAnchor)} aria-haspopup="true" onClick={event => setProfileAnchor(event.currentTarget)}>My account</Button>
      <Button startIcon={<LogOut size={18} />} onClick={HandleLogout}>Sign out</Button>
    </nav>
    <Button className="applicant-mobile-menu" startIcon={<MenuIcon size={20} />} aria-controls={mobileAnchor ? 'applicant-mobile-menu' : undefined} aria-expanded={Boolean(mobileAnchor)} aria-haspopup="true" onClick={event => setMobileAnchor(event.currentTarget)}>Menu</Button>
    <Menu id="applicant-profile-menu" anchorEl={profileAnchor} open={Boolean(profileAnchor)} onClose={() => setProfileAnchor(null)}>
      <MenuItem onClick={() => goTo('/application/update_login_detail')}>Update login details</MenuItem><MenuItem onClick={() => goTo('/application/student_support')}>Student support</MenuItem>
    </Menu>
    <Menu id="applicant-mobile-menu" anchorEl={mobileAnchor} open={Boolean(mobileAnchor)} onClose={() => setMobileAnchor(null)}>
      <MenuItem onClick={() => goTo('/application/home')}>Dashboard</MenuItem><MenuItem onClick={() => goTo('/application/update_login_detail')}>Update login details</MenuItem><MenuItem onClick={() => goTo('/application/student_support')}>Student support</MenuItem><MenuItem onClick={HandleLogout}>Sign out</MenuItem>
    </Menu>
  </div>;
}
