import OfferLetterDocument from './OfferLetterDocument';
import OfferLetterActions from './OfferLetterActions';
import React, { useContext, useEffect, useState } from "react";
import {
  Box,
  Button,
  CircularProgress
} from "@mui/material";
import PrintIcon from "@mui/icons-material/Print";
import { Link, useNavigate } from "react-router-dom";
import { ContextData } from "../../../../../../../context/Context";
import { Getrequest, Postrequest } from "../../../../../../../context/AxiosRequest";
import { toast } from "react-toastify";
import SoundAlert from "../../../../../../../routes/SoundAlert";

// 📌 Dynamic Variables (you can load this from API later)


function formatNumber(value) {
    if (value === "" || value == null) return "";
    // value is raw digits string (no decimals). Convert to number then format.
    const num = Number(value);
    if (Number.isNaN(num)) return "";
    return new Intl.NumberFormat().format(num);
}



export default function InPrincipleOfferStudentLoan({from,data,user_tokens,program_type}) {

  const handlePrint = () => {
    window.print();
    
  };

  const [checkDisburs,setcheckDisburs] = useState("yet") 
  const Navigate = useNavigate();
  const {accesstoken,UserTokens} = useContext(ContextData)
  const [ChangeLoanForm, setChangeLoanForm] = useState(null);
  const [disbursementData, setDisbursementData] = useState(null);
   // loanEv

   const [GetOffer,setGetOffer] = useState(null)

      useEffect(()=>{
    
    
            (async()=>{


                    const response = await Getrequest(`/auth/get_inpriciple_offer/${ from === "loanEv" ? user_tokens  : UserTokens}`,accesstoken)

                    const loanData = await Getrequest(`/auth/get_loan_data/${ from === "loanEv" ? user_tokens  : UserTokens}`,accesstoken)
                         
                                              
                          setGetOffer([response])   

                    if(loanData) setChangeLoanForm(loanData?.loanrequest[0]?.loan_category)


                                               if(from !== "loanEv"){
                                             
                                                const responseDisburs = await Getrequest(`/auth/get_disbursement_request/${UserTokens}`,accesstoken)
                                                 

                                                     const get_disburs = await Getrequest(`/auth/get_disbursement_request/${UserTokens}`,accesstoken)
                                                   
                                                                                 if(get_disburs?.data){
                                                           
                                                                                      
                                                                                      
                                                                                            
                                                                                            setcheckDisburs(get_disburs?.data.accept_request)
                                                   
                                                                                           // console.log(get_disburs?.data.accept_request)
                                                                 
                                                                                     }
                                                   


                                                 if(responseDisburs.status){
                                                    setDisbursementData(responseDisburs)
                                                 }else{

                                                   setDisbursementData(responseDisburs.status)
                                                 }
                                                // console.log(responseDisburs)    
                                              }
                        
    
            })()  
    
    
             
        },[])
    

        const handlePromptDecline = async() => {
          
            const confirmDecline = window.prompt("Are you sure you want to decline this offer? Please state the reason")
            // get the prompt result and send it to post request
            if(confirmDecline){
              
              const data = {
                  
                   confirmDecline,
                   user_token : UserTokens
                   
              }
                    const response = await Postrequest("/auth/deline_offer",data,accesstoken)

                     if(response.status){

                          toast.success(response.textStatus)
                          SoundAlert("success")

                     }else{

                          toast.error(response.textStatus)
                          SoundAlert("error") 

                     }

             }

          };


          
          if(from !== "loanEv" ){

            if( GetOffer !== null &&  GetOffer[0].did_accept === "declined"){
                          
                   toast.warn("You already declined your offer")
                   SoundAlert("error")
                   Navigate("/application/my_application_details")
                   return
            }



          }




    const HandleNavigate = (guarantor, amountOffered) => {

            
      

             // studentloan

       if(ChangeLoanForm === "thirdparty"){
        
        Navigate("/application/offers/utilization_letter_thirt_party")

       } else{
         
         Navigate(`/application/offers/utilization_letter_student/${guarantor}/${amountOffered}`)
       }




    }


   if(GetOffer !== null){
    if(GetOffer[0].guarantor == undefined && from !== "loanEv" ){

                    Navigate("/application/my_application_details")
                    toast.warn("Letter not found")
                    SoundAlert("error")
                    return
    }
  }



  return (
    <Box className="inprinciple-view">
      {from !== 'loanEv' && <header className="offer-view-toolbar">
        <div><Link to="/application/my_application_details" className="offer-back-link">Back to application</Link><h2>Your offer letter</h2><p>Review your loan details and the conditions below.</p></div>
        <div className="offer-toolbar-actions">
          {disbursementData === null && <Button variant="outlined" color="error" onClick={() => prompt("Are you sure you want to decline this offer?")}>Decline offer</Button>}
          <Button variant="outlined" startIcon={<PrintIcon />} onClick={handlePrint}>Print letter</Button>
        </div>
      </header>}
      {from === 'loanEv' ?
        <OfferLetterDocument offer={data} thirdParty={false} review programType={program_type} /> :
        GetOffer === null ? <Box className="offer-loading" role="status"><CircularProgress size={28} /><h2>Preparing your offer letter</h2><p>Loading your offer and loan details…</p></Box> :
        GetOffer.map((item, index) => <React.Fragment key={item.SID || index}>
          <OfferLetterDocument offer={item} thirdParty={false} />
          <OfferLetterActions checkDisburs={checkDisburs} disbursementData={disbursementData} onAccept={() => HandleNavigate(item.guarantor.replace(/\bN\/A\b/g, " ").trim(), item.Amount_Offered)} />
        </React.Fragment>)}
    </Box>
  );
}
