import React from 'react';
import { FileText, ShieldCheck } from 'lucide-react';

function formatNumber(value) {
  if (value === '' || value == null) return '—';
  const number = Number(String(value).replace(/,/g, ''));
  return Number.isNaN(number) ? String(value) : new Intl.NumberFormat().format(number);
}

function months(value) {
  return value == null || value === '' ? '—' : `${value * 12} Months`;
}

export default function OfferLetterDocument({ offer, thirdParty = false, review = false, programType }) {
  const contact = thirdParty ? offer.Sponsor : review ? offer.guarantor : String(offer.guarantor ?? '').replace(/\bN\/A\b/g, ' ').trim();
  return <article className="offer-document" id="print-area" aria-label="In-principle offer letter">
    <header className="offer-letterhead">
      <img src="/newksslb.jpg" alt="KADSSLB logo" />
      <div><span className="offer-letterhead-eyebrow">KADUNA STATE GOVERNMENT</span><h2>Scholarship and Loans Board</h2><p>Student Tertiary Education Loan ({thirdParty ? 'Third Party' : 'Student Loan'})</p></div>
    </header>
    <div className="offer-document-heading"><div><span className="offer-document-label"><FileText size={16} /> LOAN APPLICATION</span><h1>In-principle offer letter</h1></div>{!review && <div className="offer-applicant-id"><span>Applicant ID</span><strong>{offer.SID || '—'}</strong></div>}</div>
    {review && programType && <p className="offer-programme">{programType}</p>}
    <div className="offer-correspondence"><p>Dear <strong>{review && !thirdParty ? offer.Student : thirdParty ? offer.Sponsor : offer.guarantor}</strong>,</p><p>{review && !thirdParty ? 'your Loan Application has been processed by the Bank' : <>Your Loan Application has been processed by the Bank for <strong>{offer.Student}</strong>.</>}</p><p>With the following details:</p></div>
    <dl className="offer-parties"><div><dt>{thirdParty ? 'Sponsor' : 'Guarantor'}</dt><dd>{contact || '—'}</dd></div><div><dt>Student</dt><dd>{offer.Student || '—'}</dd></div></dl>
    <div className="offer-amounts"><section className="offer-amount-requested"><h3>Amount requested / Tenor</h3><p>₦ {formatNumber(offer.Amount_Requested)}</p><span>{months(offer.Amount_Requested_Tenor)}</span></section><section className="offer-amount-offered"><h3>Amount offered / Tenor</h3><p>₦ {formatNumber(offer.Amount_Offered)}</p><span>{months(offer.Amount_Offered_Tenor)}</span></section></div>
    <dl className="offer-credit-details"><div><dt>Credit report</dt><dd>{offer.Credit_Report || '—'}</dd></div><div><dt>Credit status</dt><dd>{offer.offer_status || '—'}</dd></div></dl>
    <div className="offer-condition"><ShieldCheck size={23} aria-hidden="true" /><p>Congratulations, your application has been approved in principle on the condition that you provide all necessary documents to the designated Bank.</p></div>
    <footer className="offer-document-footer"><span>KADUNA STATE SCHOLARSHIP AND LOANS BOARD</span><span>Student tertiary education loan</span></footer>
  </article>;
}
