import React, { useState } from 'react';
import { IconButton, InputAdornment, TextField } from '@mui/material';
import { Eye, EyeOff } from 'lucide-react';

export default function PasswordField({ label = 'Password', ...props }) {
  const [visible, setVisible] = useState(false);
  return <TextField {...props} label={label} type={visible ? 'text' : 'password'} InputProps={{
    ...props.InputProps,
    endAdornment: <InputAdornment position="end"><IconButton
      type="button" edge="end" aria-label={`${visible ? 'Hide' : 'Show'} ${label.toLowerCase()}`}
      aria-pressed={visible} onClick={() => setVisible(value => !value)}
      onMouseDown={event => event.preventDefault()} disabled={props.disabled}
    >{visible ? <EyeOff size={19} /> : <Eye size={19} />}</IconButton></InputAdornment>,
  }} />;
}
