export function getAdminPageDetails(pathname) {
  const key = pathname.split('/').filter(Boolean).pop();
  const [title, description, category] = adminPages[key] || ['Administration', 'Manage applications and education support programmes.', 'Workspace'];
  return { title, description, category };
}
