import React from 'react';
import { LinearProgress } from '@mui/material';
import { ClipboardList } from 'lucide-react';

export default function FormProgress({ steps, activeStep, title }) {
  const current = steps[activeStep];
  if (!current) return null;
  return <header className="form-progress-header">
    <div className="form-progress-title"><span className="form-progress-icon"><ClipboardList size={23} /></span><div><span className="form-eyebrow">{title}</span><h1>{current}</h1></div><span className="form-step-count">Step {activeStep + 1} of {steps.length}</span></div>
    <LinearProgress variant="determinate" value={((activeStep + 1) / steps.length) * 100} aria-label={`${title}: step ${activeStep + 1} of ${steps.length}`} />
    <p>{activeStep < steps.length - 1 ? `Up next: ${steps[activeStep + 1]}` : 'You are on the last section of this form.'}</p>
  </header>;
}
