import React from 'react';
import { ClipboardCheck, Users, FolderSearch, Search } from 'lucide-react';

export function ReviewIntro({ title, description, count }) {
  return <header className="review-intro">
    <span className="review-intro-icon"><ClipboardCheck size={28} /></span>
    <div><span className="review-eyebrow">APPLICATION MANAGEMENT</span><h2>{title}</h2><p>{description}</p></div>
    <div className="review-total"><strong>{count.toLocaleString()}</strong><span>Applications in this queue</span></div>
  </header>;
}

export function ReviewQueueHeading({ count }) {
  return <div className="review-queue-heading"><Users size={19} /><h3>Applicant queue</h3><span>{count}</span><p>Select an applicant to review their details.</p></div>;
}

export function ReviewEmpty({ queue = false, searching = false }) {
  const Icon = searching ? Search : FolderSearch;
  return <div className={`review-empty ${queue ? 'review-empty-queue' : ''}`} role="status">
    <span><Icon size={queue ? 26 : 38} /></span>
    <h3>{queue ? searching ? 'No matching applicants' : 'No applications in this queue' : 'Select an applicant to begin'}</h3>
    <p>{queue ? searching ? 'Try a different name, email or applicant ID.' : 'Applications will appear here when available.' : 'Choose a name from the queue to view their profile, documents and loan details.'}</p>
  </div>;
}
