import React from 'react';
import { Button } from '@mui/material';
import { CheckCircle2, FilePenLine } from 'lucide-react';

export default function OfferLetterActions({ checkDisburs, disbursementData, onAccept }) {
  const returned = checkDisburs === 'returned_request';
  const accepted = !returned && disbursementData !== null && Boolean(disbursementData);
  return <section className="offer-response-panel" aria-label="Offer response">
    <span className="offer-response-icon">{accepted ? <CheckCircle2 size={24} /> : <FilePenLine size={24} />}</span>
    <div><h2>{returned ? 'Your utilization letter needs an update' : accepted ? 'You have accepted this offer' : 'Your next step'}</h2><p>{returned ? 'Refill the form according to the requested changes.' : accepted ? 'Your offer response has been recorded.' : 'Accept and go to the next page to fill and submit the Utilization Letter.'}</p></div>
    <Button variant="contained" color="secondary" disabled={accepted} onClick={onAccept}>{returned ? 'Update utilization letter' : accepted ? 'Offer accepted by you' : 'Accept offer'}</Button>
  </section>;
}
