import * as React from 'react';
import { Banknote, GraduationCap, Check, LoaderCircle } from 'lucide-react';
import { ContextData } from '../../../../../context/Context';
import { Getrequest, Putrequest } from '../../../../../context/AxiosRequest';
import { toast } from 'react-toastify';

export default function ApplyingType() {
  const { Value, setValue, UserTokens, accesstoken } = React.useContext(ContextData);
  const [DataValue, setDataValue] = React.useState('');
  const [isSaving, setIsSaving] = React.useState(false);
  const [saveError, setSaveError] = React.useState('');
  const descriptionId = React.useId();

  // When user changes selection
  const handleChange = (event) => {
    const newValue = String(event.target.value).trim();
    if (isSaving) return;

    if (!UserTokens) {
      toast.warn('Please refresh the page');
      return;
    }

    // only send update if the value actually changed from the currently stored Value
    if (newValue === (Value ?? '')) return;

    setDataValue(newValue);
    setIsSaving(true);
    setSaveError('');

    const data = { application_type: newValue, UserTokens };

    (async function updateAppType() {
      try {
        const response = await Putrequest(`/auth/update_application_type`, data, accesstoken);
        if (response.status) {
          setValue(newValue);
          toast.success(response.textStatus);
        } else {
          setDataValue(Value ?? '');
          setSaveError(response.textStatus || 'Could not update your application type. Please try again.');
          toast.error(response.textStatus);
        }
      } catch (err) {
        setDataValue(Value ?? '');
        setSaveError('Could not update your application type. Please try again.');
        toast.error('Failed to update application type');
      } finally {
        setIsSaving(false);
      }
    })();
  };

  // Fetch current application type on mount / when tokens change
  React.useEffect(() => {
    if (!accesstoken || !UserTokens) return;

    (async function fetchAppType() {
      try {
        const response = await Getrequest(`/auth/get_app_type/${UserTokens}`, accesstoken);
        const fetched = String(response?.[0]?.application_type ?? '').trim();
        if (fetched) {
          setDataValue(fetched);
          setValue(fetched); // sync context
        } else {
          setDataValue('');
        }
      } catch (err) {
        toast.error('Failed to fetch application type');
      }
    })();
  }, [accesstoken, UserTokens, setValue]);

  return (
    <fieldset className="application-type-picker" aria-describedby={descriptionId} aria-busy={isSaving} disabled={isSaving}>
      <legend>Application type</legend>
      <p id={descriptionId} className="application-type-help">Choose the programme for your application.</p>
      <div className="application-type-options">
        {[
          { value: 'loan', title: 'Education loan', description: 'Financial support for tertiary education.', Icon: Banknote },
          { value: 'scholarship', title: 'Scholarship', description: 'Explore scholarship support for your studies.', Icon: GraduationCap },
        ].map(({ value, title, description, Icon }) => <label key={value} className={`application-type-option ${DataValue === value ? 'is-selected' : ''}`}>
          <input type="radio" name="applicationtype" value={value} checked={DataValue === value} onChange={handleChange} />
          <span className="application-type-option-icon" aria-hidden="true"><Icon size={22} /></span>
          <span className="application-type-option-copy"><strong>{title}</strong><span>{description}</span></span>
          <span className="application-type-check" aria-hidden="true">{DataValue === value && <Check size={14} strokeWidth={3} />}</span>
        </label>)}
      </div>
      <div className="application-type-feedback" role="status">{isSaving ? <><LoaderCircle size={14} className="application-type-spinner" aria-hidden="true" /> Saving your selection…</> : saveError ? <span className="application-type-error">{saveError}</span> : <><Check size={14} aria-hidden="true" /> {DataValue ? `${DataValue === 'loan' ? 'Education loan' : 'Scholarship'} selected` : 'Your current application type will appear here.'}</>}</div>
    </fieldset>
  );
}
