import React from 'react';

export default function ApplicantTaskCard({ step, title, description, icon, extra, onClick }) {
  return <li className="applicant-task-item">
    <button type="button" className="applicant-task-card" onClick={onClick}>
      <span className="applicant-task-top"><span className="applicant-task-icon" aria-hidden="true">{icon}</span><span className="applicant-task-step">Step {step}</span></span>
      <span className="applicant-task-title">{title}</span>
      <span className="applicant-task-description">{description}</span>
      {extra && <span className="applicant-task-progress">{extra}</span>}
      <span className="applicant-task-action">{step === 6 ? 'View application' : 'Open section'}</span>
    </button>
  </li>;
}
