import React from 'react';
import LinearProgress from '@mui/material/LinearProgress';
import Box from '@mui/material/Box';

export default function FormLoaderStep({ value }) {
  const progress = value == null || value === '' ? null : Number(value);
  const available = progress !== null && Number.isFinite(progress);
  const percentage = available ? Math.min(100, Math.max(0, Math.round(progress))) : 0;
  return <Box component="span" className="profile-card-progress" sx={{ display: 'block', width: '100%' }}>
    <Box component="span" sx={{ display: 'flex', justifyContent: 'space-between', gap: 1, mb: 1, color: '#365768', fontSize: '0.8125rem', fontWeight: 500 }}>
      <span>Profile progress</span><span>{available ? `${percentage}%` : 'Loading…'}</span>
    </Box>
    <LinearProgress variant={available ? 'determinate' : 'indeterminate'} value={percentage} aria-label="Profile completion" sx={{ height: 5, borderRadius: 3, bgcolor: '#e5eeeb', '& .MuiLinearProgress-bar': { bgcolor: '#087c60' } }} />
  </Box>;
}
