import React, { useId } from 'react';
import { Dialog, DialogTitle, IconButton } from '@mui/material';
import { X } from 'lucide-react';

export default function AdminDialog({ children, heading, onClose, maxWidth = 'sm', fullWidth = true, fullScreen = false, className = '', ...props }) {
  const titleId = useId();
  const content = React.Children.toArray(children);
  const hasTitle = content.some(child => React.isValidElement(child) && child.type === DialogTitle);
  return <Dialog {...props} className={`admin-dialog ${className}`} onClose={onClose} maxWidth={maxWidth || 'lg'} fullWidth={fullWidth} fullScreen={fullScreen}
    aria-labelledby={heading || hasTitle ? titleId : props['aria-labelledby']}
    aria-label={!heading && !hasTitle && !props['aria-labelledby'] ? 'Administration dialog' : props['aria-label']}>
    {heading && <DialogTitle id={titleId}>{heading}</DialogTitle>}
    {onClose && !fullScreen && <IconButton className="admin-dialog-close" aria-label="Close dialog" onClick={event => onClose(event, 'closeButton')}><X size={20} /></IconButton>}
    {content.map(child => React.isValidElement(child) && child.type === DialogTitle ? React.cloneElement(child, { id: titleId }) : child)}
  </Dialog>;
}
