import React, { useContext, useEffect, useState } from "react";
import { Outlet, useNavigate, useLocation } from "react-router-dom";
import { ContextData } from "../../../context/Context";
import GetPersonData from "../../../context/GetPersonData";
import { Settings2, LockKeyhole, FileText, Building2, Landmark, SlidersHorizontal } from "lucide-react";
import GetAdminCredentials from "../../../context/GetAdminCredentials";

function Settings() {

  const [searchText, setSearchText] = useState("");

  const handleSearchChange = (e) => {
    setSearchText(e.target.value);
  };

  const Navigate = useNavigate();
  const location = useLocation();

  const [Changeroutes,setChangeroutes] = React.useState(null)
  const {Checker,UserTokens,accesstoken} = useContext(ContextData)
  const [UserType,setUserType] = React.useState("")

   const  user_roles = [
          "Administrator",
          "Manage",
          "Selector",
          "Validator",
          "Verifier",
          "Bank reviewer",
          "account-helper",
          "Manage Loan",
          "Manage Scholarship",
          "Manage Loan General"
           ]


      React.useEffect(()=>{
  
          (async ()=>{
  
                  GetAdminCredentials(UserTokens,accesstoken).then(res =>{
                       setUserType(res)
                  })
                 
          })()
  
  
  
      },[]) 
  

    useEffect(()=>{
          
          

        if(UserType[0]?.acct_typ === user_roles[0]){

           setChangeroutes( [
           
            {
              path: "update-password",
              name: "Update Password",
            },
            {
              path: "limitscholarship",
              name: "Limit Scholarship",
            },

            {
              path: "add-document",
              name: "Add Document",
            },
            {
              path: "upload-document",
              name: "Loan Documents Download",
            },
            {
              path: "add-university",
              name: "Add University",
            },
            {
              path: "add-bank",
              name: "Add Bank",
            }
            
          ])
 





        }else if(UserType[0]?.acct_typ === user_roles[7] ){

           setChangeroutes( [
           
            {
              path: "update-password",
              name: "Update Password",
            }
            
          ])
 





        }else if(UserType[0]?.acct_typ === user_roles[9] ){

           setChangeroutes( [
           
            {
              path: "update-password",
              name: "Update Password",
            },

            {
              path: "add-document",
              name: "Add Document",
            },
            {
              path: "upload-document",
              name: "Loan Documents Download",
            }
            
          ])
 





        } else if(user_roles.filter(role => role !== user_roles[0] && role !== user_roles[7]).includes(UserType[0]?.acct_typ) ){


           setChangeroutes( [
           
            {
              path: "update-password",
              name: "Update Password",
            }
            
          ])
           
             

        }





    },[UserType])
 

  const icons = { 'update-password': LockKeyhole, 'limitscholarship': SlidersHorizontal, 'add-document': FileText, 'upload-document': FileText, 'add-university': Building2, 'add-bank': Landmark };
  const settingsRoot = location.pathname.endsWith('/settings');
  return <div className="admin-settings-layout">
    <nav className="admin-settings-nav" aria-label="Settings navigation"><span className="admin-settings-caption">CONFIGURATION</span>{Changeroutes && Changeroutes.map(item => {
      const Icon = icons[item.path] || Settings2;
      const active = location.pathname.endsWith(`/${item.path}`);
      return <button type="button" key={item.path} className={active ? 'is-active' : ''} aria-current={active ? 'page' : undefined} onClick={() => Navigate(item.path)}><Icon size={18} /><span>{item.name}</span></button>;
    })}</nav>
    <div className="admin-settings-content">{settingsRoot && <div className="admin-settings-empty"><Settings2 size={42} /><h2>Make the workspace work for you.</h2><p>Choose a setting to manage your account or configure the programmes available to your role.</p></div>}<Outlet /></div>
  </div>;
}

export default Settings;
